{
  "claims": [
    {
      "claim": "Cephradine, a close structural analogue with the same 3-methyl-cephem core and an aminocephalosporin side chain, showed complete or high oral bioavailability in humans (85–100%), supporting F ≥20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 1", "Molecule 2"],
      "record_ids": ["Record 1-1", "Record 2-1", "Record 2-2", "Record 2-3", "Record 2-4", "Record 2-5"]
    },
    {
      "claim": "Amoxicillin, which shares the p-hydroxyphenylglycyl side chain, had absolute oral bioavailability of 70–88.7% in fasted healthy subjects, and amoxicillin/clavulanate was reported as 90% bioavailable, all well above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 4", "Molecule 5"],
      "record_ids": ["Record 4-1", "Record 5-1", "Record 5-2", "Record 5-3"]
    },
    {
      "claim": "Loracarbef, a close carbacephem analogue, was at least 80–90% bioavailable and essentially completely absorbed in humans.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 8"],
      "record_ids": ["Record 8-1", "Record 8-2", "Record 8-3", "Record 8-4"]
    },
    {
      "claim": "Cefroxadine, another 3-substituted oral cephalosporin, showed nearly 100% oral bioavailability, and a structurally similar cephalosporin (SP) showed ~40% human oral bioavailability.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 6", "Molecule 9"],
      "record_ids": ["Record 6-1", "Record 9-1"]
    },
    {
      "claim": "Ampicillin, a related aminopenicillin, had 29% absolute oral bioavailability in fasted female subjects, still above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 10"],
      "record_ids": ["Record 10-1"]
    },
    {
      "claim": "Cephalexin, the closest non-hydroxylated analogue, is extremely well absorbed in humans, with fraction absorbed values of 0.9–1.0 and high PEPT1-mediated intestinal permeability; human F is approximately 90%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 14", "Molecule 15", "Molecule 16"],
      "record_ids": ["Record 14-1", "Record 14-2", "Record 14-7", "Record 14-8", "Record 14-12", "Record 14-13", "Record 14-17", "Record 15-1", "Record 15-4", "Record 15-6", "Record 15-9", "Record 15-10", "Record 15-11", "Record 16-1"]
    },
    {
      "claim": "Other cephalexin bioavailability reports of 35%, 34.8%, 35%, and 83% (PEPT1-absent simulation) are at or above the 20% threshold, and an oral 250 mg cephalexin AUC of 19.2 µg·h/mL indicates substantial exposure.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 11", "Molecule 12"],
      "record_ids": ["Record 11-6", "Record 11-9", "Record 11-10", "Record 11-12", "Record 12-1"]
    },
    {
      "claim": "Fed-state evidence from trans-cefprozil, a p-hydroxyphenylglycyl cephalosporin, showed measurable oral AUC after 125 mg under fed conditions, supporting absorption in the fed state.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 13"],
      "record_ids": ["Record 13-1"]
    },
    {
      "claim": "Low oral bioavailability values for cefazolin (1.5–2%), ceftriaxone (8%), and cephalexin in horses (5%) or under coadministration/control conditions (14.2%, 18.8%) are contradictory, but these are structurally distant or species/condition-specific and are outweighed by direct human data.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 3", "Molecule 7", "Molecule 11"],
      "record_ids": ["Record 3-1", "Record 7-1", "Record 11-1", "Record 11-2", "Record 11-3", "Record 11-4", "Record 11-5", "Record 11-7", "Record 11-8"]
    },
    {
      "claim": "A high-protein diet decreased cephalexin absorption in perfusion experiments, but this is not an affirmative F<20% result and does not overturn the human high-absorption evidence.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 14"],
      "record_ids": ["Record 14-3"]
    },
    {
      "claim": "Molecule 17 (hepatic clearance in a rat renal-failure model) is not informative for the oral F threshold and is given little weight.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 17"],
      "record_ids": ["Record 17-1"]
    }
  ],
  "final_prediction": "pass"
}
